svg.script:
(function() {
  const METADATA = {"assetId":"fancy_feast_tuna_feast_in_gravy_grilled","name":"Fancy Feast Tuna Feast in Gravy Grilled","category":"Food - Wet","interactiveType":"wet_food","emits":["food.wet"],"accepts":[],"slots":[],"sourcePng":"fancy_feast_tuna_feast_in_gravy_grilled.png","audioKeys":["open_can","pour"]};
  const ROLE = "source";
  const EMITS = ["food.wet"];
  const ACCEPTS = [];
  const SLOTS = [];
  const SOUND_URIS = {"open_can": "data:audio/mpeg;base64,", "pour": "data:audio/mpeg;base64,"};
  const STATE = {
    assetId: METADATA.assetId,
    role: ROLE,
    running: false,
    waterLevel: 1,
    slotLevels: {},
    slotModes: {},
    lastAction: null
  };
  for (const slot of SLOTS) {
    STATE.slotLevels[slot.id] = 0;
    STATE.slotModes[slot.id] = slot.accepts && slot.accepts.length === 1 ? slot.accepts[0] : null;
  }

  const _audio = {};
  function getAudio(name) {
    if (!SOUND_URIS[name]) return null;
    if (!_audio[name]) {
      _audio[name] = new Audio(SOUND_URIS[name]);
      if (name === 'water_loop') _audio[name].loop = true;
    }
    return _audio[name];
  }
  function playAudio(name) {
    const a = getAudio(name); if (!a) return;
    try { a.currentTime = 0; a.play(); } catch (e) {}
  }
  function setLoop(name, on) {
    const a = getAudio(name); if (!a) return;
    try {
      if (on) { a.loop = true; a.play(); }
      else { a.pause(); }
    } catch (e) {}
  }
  function clamp(v,min,max) { return Math.max(min, Math.min(max, v)); }
  function show(el, on) { if (el) el.style.display = on ? 'inline' : 'none'; }

  function updateBowls() {
    for (const slot of SLOTS) {
      const level = clamp(STATE.slotLevels[slot.id] || 0, 0, 1);
      const mode = STATE.slotModes[slot.id];
      const dry = document.getElementById(slot.id + '-dry');
      const wet = document.getElementById(slot.id + '-wet');
      show(dry, mode === 'food.dry' || mode === 'treat.crunchy' || mode === 'treat.freeze_dried');
      show(wet, mode === 'food.wet' || mode === 'treat.lickable');
      [dry, wet].forEach(g => {
        if (!g) return;
        const fill = g.querySelector('.food-fill');
        if (fill) {
          fill.style.transform = 'translateY(' + ((1 - level) * 26) + 'px) scaleY(' + Math.max(0.08, level) + ')';
          fill.style.opacity = level <= 0.001 ? '0' : '1';
        }
      });
    }
  }

  function updateFountain() {
    const water = document.getElementById('fountain-water-overlays');
    if (!water) return;
    water.classList.toggle('water-off', !STATE.running);
    water.classList.toggle('water-on', !!STATE.running);
    water.style.opacity = String(clamp(0.25 + STATE.waterLevel * 0.75, 0.25, 1));
  }

  function chooseSlot(payloadId) {
    for (const slot of SLOTS) {
      if ((slot.accepts || []).includes(payloadId)) return slot;
    }
    return SLOTS[0] || null;
  }

  function receive(payloadId, amount=0.25, sourceId='') {
    STATE.lastAction = 'receive:' + payloadId;
    if (ROLE === 'bowl') {
      const slot = chooseSlot(payloadId);
      if (!slot) return {accepted:false, reason:'no-slot'};
      STATE.slotModes[slot.id] = payloadId;
      STATE.slotLevels[slot.id] = clamp((STATE.slotLevels[slot.id] || 0) + amount, 0, 1);
      updateBowls();
      if (payloadId.startsWith('food.')) playAudio('eat');
      return {accepted:true, slotId:slot.id, level:STATE.slotLevels[slot.id], payloadId, sourceId};
    }
    if (ROLE === 'fountain') {
      if (payloadId !== 'water.clean') return {accepted:false, reason:'wrong-payload'};
      STATE.waterLevel = clamp(STATE.waterLevel + amount, 0, 1);
      STATE.running = true;
      updateFountain();
      setLoop('water_loop', true);
      return {accepted:true, waterLevel:STATE.waterLevel};
    }
    return {accepted:false, reason:'not-receiver'};
  }

  function consume(slotId, amount=0.1) {
    if (ROLE !== 'bowl') return null;
    slotId = slotId || (SLOTS[0] && SLOTS[0].id);
    if (!slotId) return null;
    STATE.slotLevels[slotId] = clamp((STATE.slotLevels[slotId] || 0) - amount, 0, 1);
    updateBowls();
    playAudio('eat');
    return getState();
  }

  function drink(amount=0.1) {
    if (ROLE !== 'fountain') return null;
    STATE.waterLevel = clamp(STATE.waterLevel - amount, 0, 1);
    updateFountain();
    playAudio('drink');
    return getState();
  }

  function setRunning(on) {
    if (ROLE !== 'fountain') return;
    STATE.running = !!on;
    updateFountain();
    setLoop('water_loop', !!on);
  }

  function play(action) {
    STATE.lastAction = action;
    if (action === 'shake') { playAudio('treat_shake'); playAudio('treat_shake_quick'); }
    if (action === 'pour') playAudio('pour');
    if (action === 'open') playAudio('open_can');
    if (action === 'eat') playAudio('eat');
    if (action === 'drink') playAudio('drink');
    if (action === 'startWater') setRunning(true);
    if (action === 'stopWater') setRunning(false);
    return true;
  }

  function getState() {
    return JSON.parse(JSON.stringify(STATE));
  }

  function setSlotMode(slotId, payloadId) {
    if (!(slotId in STATE.slotModes)) return false;
    STATE.slotModes[slotId] = payloadId;
    updateBowls();
    return true;
  }

  function setLevel(slotId, level) {
    if (ROLE === 'fountain') {
      STATE.waterLevel = clamp(level,0,1); updateFountain(); return true;
    }
    if (!(slotId in STATE.slotLevels)) return false;
    STATE.slotLevels[slotId] = clamp(level,0,1);
    updateBowls();
    return true;
  }

  function emitPayload() { return EMITS.slice(); }
  function acceptedPayloads() { return ACCEPTS.slice(); }

  window.OnyxSVGAsset = {
    metadata: METADATA,
    getState,
    receive,
    consume,
    drink,
    play,
    emitPayload,
    acceptedPayloads,
    setLevel,
    setSlotMode,
    setRunning,
  };
  updateBowls();
  updateFountain();
  if (ROLE === 'fountain' && STATE.running) setLoop('water_loop', true);
})();
